REPLACE INTO `wp_posts` VALUES (9,1,'2026-11-18 16:00:29','2026-11-18 16:00:29','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--60)\">\n	<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"metadata\":{\"patternName\":\"twentytwentyfive/hidden-blog-heading\",\"name\":\"Hidden blog heading\",\"description\":\"Hidden heading for the home page and index template.\"}} -->\n<h1 class=\"wp-block-heading has-text-align-left\">Blog</h1>\n<!-- /wp:heading -->\n	<!-- wp:query {\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":true,\"taxQuery\":null,\"parents\":[]},\"align\":\"full\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"twentytwentyfive/template-query-loop\",\"name\":\"List of posts, 1 column\",\"description\":\"A list of posts, 1 column, with featured image and post date.\",\"categories\":[\"query\"]}} -->\n<div class=\"wp-block-query alignfull\">\n	<!-- wp:post-template {\"align\":\"full\",\"layout\":{\"type\":\"default\"}} -->\n		<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n		<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n			<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"3/2\"} /-->\n			<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"x-large\"} /-->\n			<!-- wp:post-content {\"align\":\"full\",\"fontSize\":\"medium\",\"layout\":{\"type\":\"constrained\"}} /-->\n			<!-- wp:post-date {\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}},\"fontSize\":\"small\"} /-->\n		</div>\n		<!-- /wp:group -->\n	<!-- /wp:post-template -->\n	<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n	<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n		<!-- wp:query-no-results -->\n		<!-- wp:paragraph -->\n		<p>Sorry, but nothing was found. Please try a search with different keywords.</p>\n		<!-- /wp:paragraph -->\n		<!-- /wp:query-no-results -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\"}} -->\n	<div class=\"wp-block-group alignwide\">\n		<!-- wp:query-pagination {\"paginationArrow\":\"arrow\",\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\"}} -->\n			<!-- wp:query-pagination-previous /-->\n			<!-- wp:query-pagination-numbers /-->\n			<!-- wp:query-pagination-next /-->\n		<!-- /wp:query-pagination -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:query -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Edited home</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->\n','Blog Home','Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.','publish','closed','closed','','home','','','2026-11-18 16:00:29','2026-11-18 16:00:29','',0,'http://127.0.0.1:8081/?p=9',0,'wp_template','',0);
REPLACE INTO `wp_posts` VALUES (10,1,'2026-11-18 16:00:29','2026-11-18 16:00:29','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--60)\">\n	<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n	<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n		<!-- wp:post-title {\"level\":1} /-->\n		<!-- wp:post-featured-image {\"aspectRatio\":\"3/2\"} /-->\n		<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0.2em\",\"margin\":{\"bottom\":\"var:preset|spacing|60\"}}},\"fontSize\":\"small\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"},\"metadata\":{\"patternName\":\"twentytwentyfive/hidden-written-by\",\"name\":\"Written by\"}} -->\n<div class=\"wp-block-group has-small-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--60)\">\n	<!-- wp:paragraph -->\n	<p>Written by </p>\n	<!-- /wp:paragraph -->\n	<!-- wp:post-author-name {\"isLink\":true} /-->\n	<!-- wp:paragraph -->\n	<p>in</p>\n	<!-- /wp:paragraph -->\n	<!-- wp:post-terms {\"term\":\"category\",\"style\":{\"typography\":{\"fontWeight\":\"300\"}}} /-->\n</div>\n<!-- /wp:group -->\n		<!-- wp:post-content {\"align\":\"full\",\"layout\":{\"type\":\"constrained\"}} /-->\n		<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n		<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n			<!-- wp:post-terms {\"term\":\"post_tag\",\"separator\":\"  \",\"className\":\"is-style-post-terms-1\"} /-->\n		</div>\n		<!-- /wp:group -->\n		\n		<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"twentytwentyfive/post-navigation\",\"name\":\"Post navigation\",\"description\":\"Next and previous post links.\",\"categories\":[\"text\"]}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-top:var(--wp--preset--spacing--60);margin-bottom:var(--wp--preset--spacing--60)\">\n	<!-- wp:group {\"ariaLabel\":\"Post navigation\",\"tagName\":\"nav\",\"align\":\"wide\",\"style\":{\"border\":{\"top\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n	<nav class=\"wp-block-group alignwide\" aria-label=\"Post navigation\" style=\"border-top-color:var(--wp--preset--color--accent-6);border-top-width:1px;padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40)\">\n		<!-- wp:post-navigation-link {\"type\":\"previous\",\"showTitle\":true,\"arrow\":\"arrow\"} /-->\n		<!-- wp:post-navigation-link {\"showTitle\":true,\"arrow\":\"arrow\"} /-->\n	</nav>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n		<!-- wp:comments {\"className\":\"wp-block-comments-query-loop\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"}}},\"metadata\":{\"patternName\":\"twentytwentyfive/comments\",\"name\":\"Comments\",\"description\":\"Comments area with comments list, pagination, and comment form.\",\"categories\":[\"text\"]}} -->\n<div class=\"wp-block-comments wp-block-comments-query-loop\" style=\"margin-top:var(--wp--preset--spacing--70);margin-bottom:var(--wp--preset--spacing--70)\">\n	<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n	<h2 class=\"wp-block-heading has-x-large-font-size\">Comments</h2>\n	<!-- /wp:heading -->\n	<!-- wp:comments-title {\"level\":3,\"fontSize\":\"large\"} /-->\n	<!-- wp:comment-template -->\n	<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|50\"}}}} -->\n	<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:var(--wp--preset--spacing--50)\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:avatar {\"size\":50} /-->\n			<!-- wp:group -->\n			<div class=\"wp-block-group\">\n				<!-- wp:comment-date /-->\n				<!-- wp:comment-author-name /-->\n				<!-- wp:comment-content /-->\n				<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n				<div class=\"wp-block-group\">\n					<!-- wp:comment-edit-link /-->\n					<!-- wp:comment-reply-link /-->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n	<!-- /wp:comment-template -->\n\n	<!-- wp:comments-pagination {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\"}} -->\n	<!-- wp:comments-pagination-previous /-->\n	<!-- wp:comments-pagination-next /-->\n	<!-- /wp:comments-pagination -->\n\n	<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"},\"metadata\":{\"patternName\":\"twentytwentyfive/more-posts\",\"name\":\"More posts\",\"description\":\"Displays a list of posts with title and date.\",\"categories\":[\"query\"]}} -->\n<div class=\"wp-block-group alignwide\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n	<!-- wp:heading {\"align\":\"wide\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"700\",\"letterSpacing\":\"1.4px\"}},\"fontSize\":\"small\"} -->\n	<h2 class=\"wp-block-heading alignwide has-small-font-size\" style=\"font-style:normal;font-weight:700;letter-spacing:1.4px;text-transform:uppercase\">More posts</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:query {\"query\":{\"perPage\":4,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false,\"taxQuery\":null,\"parents\":[]},\"align\":\"wide\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-query alignwide\">\n		<!-- wp:post-template {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n			<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"bottom\":{\"color\":\"var:preset|color|accent-6\",\"width\":\"1px\"},\"top\":[],\"right\":[],\"left\":[]}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\",\"justifyContent\":\"space-between\"}} -->\n			<div class=\"wp-block-group alignfull\" style=\"border-bottom-color:var(--wp--preset--color--accent-6);border-bottom-width:1px;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\">\n				<!-- wp:post-title {\"level\":3,\"isLink\":true,\"fontSize\":\"large\"} /-->\n				<!-- wp:post-date {\"textAlign\":\"right\",\"isLink\":true} /-->\n			</div>\n			<!-- /wp:group -->\n		<!-- /wp:post-template -->\n	</div>\n	<!-- /wp:query -->\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Edited single</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->\n','Single Posts','Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.','publish','closed','closed','','single','','','2026-11-18 16:00:29','2026-11-18 16:00:29','',0,'http://127.0.0.1:8081/?p=10',0,'wp_template','',0);
